  var txt={on:"On duty",off:"Off duty",soon:"Back in "+plural(c.remaining,"day"),today:"Due back today",overdue:"Overdue "+plural(-c.remaining,"day"),scheduled:"Starts in "+plural(c.toStart,"day")}[c.status];
  return '<span class="pill '+STATUS_CLS[c.status]+'">'+esc(txt)+'</span>';
