function autoQueue(){return cache.queue.filter(function(it){return autoFor(it.stage)&&recipientsOf(it.e).length>0;});}
function recipientsOf(e){
  var out=[],en=waNum(e.employeePhone),sn=waNum(e.supervisorPhone);
  if(en&&en!==SENDER_WA)out.push(["employee",en]);
  if(sn&&toSupervisor()&&sn!==en&&sn!==SENDER_WA)out.push(["supervisor",sn]);
  return out;
}
function recipsHTML(e){
  var en=waNum(e.employeePhone),sn=waNum(e.supervisorPhone),parts=[];
  if(!recipientsOf(e).length)return '<p class="recips"><span class="bad">Can\'t go out automatically: no WhatsApp number on file.</span></p>';
  parts.push(en&&en!==SENDER_WA?'the employee on <b class="mono">'+esc(fmtPhone(en))+'</b>':'<span class="bad">no employee number</span>');
  if(toSupervisor()){
    if(sn&&sn!==en&&sn!==SENDER_WA)parts.push('the supervisor on <b class="mono">'+esc(fmtPhone(sn))+'</b>');
    else if(sn&&sn===en)parts.push('<span class="muted">not the supervisor (same number)</span>');
    else parts.push('<span class="muted">no supervisor (no number)</span>');
  }
  return '<p class="recips">Goes to '+parts.join(" and ")+'.</p>';
}
