function nextReminderText(){
  var t=todayISO(),best=null,T=tpls();
  cache.rows.forEach(function(r){
    var c=r.c;if(!c||c.status==="scheduled"&&false)return;
    STAGES.forEach(function(s){
      var due=addDays(c.back,-STAGE_DAYS[s]);
      if(due>t&&!sentRec(r.e,c.start,s)&&(!best||due<best.due))best={due:due,e:r.e,s:s};
    });
  });
  if(!best)return "No upcoming reminders.";
  return "Next: "+T[best.s].label+" for "+(best.e.name||("#"+best.e.id))+" on "+wday(best.due)+" "+dShort(best.due)+".";
}
