/* ================= WhatsApp replies and read receipts (from Storage by Zapier) ================= */
function digitsOf(x){return String(x||"").replace(/\D/g,"");}
function phoneIndex(){
  var m={};
  data.employees.forEach(function(e){
    var en=waNum(e.employeePhone),sn=waNum(e.supervisorPhone);
    if(en&&!m[en])m[en]={e:e,role:"employee"};
    if(sn&&!m[sn])m[sn]={e:e,role:"supervisor",many:0};
    if(sn&&m[sn].role==="supervisor"&&m[sn].e!==e)m[sn].many=(m[sn].many||0)+1;
  });
  return m;
}
/* Zap keys: r<unix>_<from> = "from|unix|type|text…"   s<unix>_<recipient>_<status> = "recipient|unix|status|messageId" */
var WA_TYPES="text|image|video|document|audio|sticker|location|contacts|interactive|button|reaction|order|system|unsupported|unknown";
function parseStoreItems(obj){
  var out=[];
  Object.keys(obj||{}).forEach(function(k){
    var v=obj[k];v=v==null?"":String(v);
    var km=/^([rs])(\d{9,11})_\W{0,2}\+?(\d{6,15})(?:_([a-z]+))?/i.exec(k);if(!km)return;
    var kind=km[1].toLowerCase()==="r"?"reply":"status",ts=parseInt(km[2],10),phone=km[3],kst=(km[4]||"").toLowerCase();
    var p=v.indexOf("|")>=0?v.split("|"):null,rest=v;
    if(!p){ /* no separators: strip the known phone and timestamp from the front */
      rest=rest.replace(/^\+/,"");
      if(rest.indexOf(phone)===0)rest=rest.slice(phone.length);
      if(rest.indexOf(String(ts))===0)rest=rest.slice(String(ts).length);
    } else { if(digitsOf(p[0]))phone=digitsOf(p[0]);var pt=parseInt(p[1],10);if(isFinite(pt)&&pt>1e9)ts=pt; }
    var at=isFinite(ts)&&ts>1e9?new Date(ts*1000).toISOString():new Date().toISOString();
    var id=k.replace(/[^A-Za-z0-9_\-.~:@+]/g,"-").slice(0,200);
    if(kind==="reply"){
      var type="text",text="";
      if(p){type=(p[2]||"text").toLowerCase();text=p.slice(3).join("|");}
      else{var tm=new RegExp("^("+WA_TYPES+")","i").exec(rest);if(tm){type=tm[1].toLowerCase();text=rest.slice(tm[1].length);}else text=rest;}
      out.push({key:k,id:id,kind:"reply",phone:phone,at:at,type:type,text:text});
    } else {
      var st=kst,mid="";
      if(p){st=(p[2]||kst).toLowerCase();mid=p[3]||"";}
      else{var sm=/^(read|failed|delivered|sent)/i.exec(rest);if(sm){st=st||sm[1].toLowerCase();mid=rest.slice(sm[1].length);}else mid=rest;}
      if(!st)return;
      out.push({key:k,id:id,kind:"status",phone:phone,at:at,status:st,msgId:mid});
    }
  });
  return out;
}
function syncInbox(quiet){
  if(!zapReady()||ui.syncing||!db)return Promise.resolve(false);
  ui.syncing=true;renderToday();
  var have={};data.wa.forEach(function(w){have[w._id]=true;});
  var stored=[];
  return zapCall(ZAP.read,{selected_api:STORE.api,action:STORE.getAll,params:{}}).then(function(res){
    var p=zapPayload(res),bad=zapToolError(p);if(bad)throw {code:"tool_error",message:bad};
    var obj=(p&&Array.isArray(p.results)?p.results[0]:p)||{};
    var items=parseStoreItems(obj),fresh=items.filter(function(it){return !have[it.id];});
    items.forEach(function(it){if(have[it.id])stored.push(it.key);});
    var i=0,now=new Date().toISOString();
    function next(){
      if(i>=fresh.length)return Promise.resolve();
      var it=fresh[i++],doc={kind:it.kind,phone:it.phone,at:it.at,syncedAt:now,syncedBy:me.id||null};
      if(it.kind==="reply"){doc.type=it.type;doc.text=it.text.slice(0,4000);doc.handled=false;}else{doc.status=it.status;doc.msgId=it.msgId;}
      return withRetry(function(){return db.collection("wa").doc(it.id).set(doc);}).then(function(){stored.push(it.key);},noop).then(next);
    }
    return next().then(function(){
      if(!stored.length)return;
      var kv={};stored.forEach(function(k){kv[k]="";});
      return zapCall(ZAP.exec,{selected_api:STORE.api,action:STORE.setMany,params:{keys_values:kv}}).catch(noop);
    }).then(function(){
      return db.doc("meta/inbox").set({lastSync:now,lastSyncBy:me.id||null,lastCount:fresh.length}).catch(noop);
    }).then(function(){
      var nr=fresh.filter(function(x){return x.kind==="reply";}).length;
      if(!quiet)toast(nr?(nr===1?"1 new reply":nr+" new replies")+" from WhatsApp.":fresh.length?"Read receipts updated. No new replies.":"No new replies.");
      return true;
    });
  }).catch(function(err){if(!quiet)toast(zapErrMsg(err),true);return false;})
  .then(function(v){ui.syncing=false;scheduleRender();return v;});
}
function maybeAutoSync(){
  if(!zapReady()||lsGet("rc-zap-used")!=="1")return;
  var last=data.inboxMeta&&data.inboxMeta.lastSync,age=last?Date.now()-new Date(last).getTime():Infinity;
  if(age>12*3600*1000)syncInbox(true);
}
function waReplies(){return data.wa.filter(function(w){return w.kind==="reply";});}
