  if(!dl){toast("Downloads aren't available in this view.",true);return;}
  var sum=[[CO_LINE],["Rotation Control: monthly report"],["Month",monthLabel(D.ym)],["Period",D.a+" to "+D.b],["Created",fmtDT(new Date().toISOString())],[],
    ["Employees",T.employees],["Returns logged",T.returns],["Returned on time",T.onTime],["Late returns",T.late],["Late days (not covered by leave)",T.lateDays],["Late days covered by leave",T.excused],["Absence notices sent",T.notices],
    ["Reminders sent automatically",T.auto],["Reminders sent by hand",T.manual],["Automatic WhatsApp messages",T.msgs],["Meta charges, approx. AED",+(T.msgs*META_AED).toFixed(2)]];
  Object.keys(LEAVE_TYPES).forEach(function(k){sum.push([LEAVE_TYPES[k]+" days",T.leaveDays[k]]);});
  var sheets=[
    {name:"Summary",rows:sum,widths:[36,26],bold:[0,1]},
    {name:"Employees",bold:[0],widths:[13,26,14,16,9,12,10,15,11,11],rows:[["Employee No.","Name","Position","Site","Returns","Late returns","Late days","Absence notices","Leave days","Reminders"]].concat(D.rows.map(function(o){return [o.e.id,o.e.name||"",o.e.position||"",o.e.site||"",o.returns,o.late,o.lateDays,o.notices,o.leaveDays,o.reminders];}))},
    {name:"Returns",bold:[0],widths:[13,26,16,12,12,10,17,17],rows:[["Employee No.","Name","Rotation started","Due back","Returned","Days late","Covered by leave","Late days counted"]].concat(D.returns.map(function(q){return [q.e.id,q.e.name||"",q.x.h.dutyStart||"",q.x.h.expectedBack,q.x.h.returnedOn,Math.max(0,q.x.d),q.x.exc,q.x.un];}))},
    {name:"Reminders",bold:[0],widths:[12,13,26,30,12,10],rows:[["Date","Employee No.","Name","Reminder","How","Messages"]].concat(D.reminders.map(function(q){return [localDateOf(q.at)||"",q.e.id,q.e.name||"",T2[q.stage]?T2[q.stage].label:q.stage,q.via,q.n||""];}))},
    {name:"Leave",bold:[0],widths:[13,26,17,12,12,16,40],rows:[["Employee No.","Name","Type","First day","Last day","Days this month","Note"]].concat(D.leaves.map(function(q){return [q.e.id,q.e.name||"",LEAVE_TYPES[q.l.type],q.l.from,q.l.to,q.days,q.l.note];}))}
  ];
