    h+='<div class="tpl-grid"><div><label class="sr" for="tplBody-'+k+'">Message</label><textarea id="tplBody-'+k+'" data-tpl-in="'+k+'" rows="7"'+(ro?" readonly":"")+'>'+esc(body)+'</textarea>'+
      (ro?'':'<div class="ph-row"><span>Insert</span>'+PLACEHOLDERS.map(function(p){return '<button type="button" class="ph" data-act="tpl-ins" data-stage="'+k+'" data-ph="'+p+'">{{'+p+'}}</button>';}).join("")+'</div>')+'</div>';
