function autoSendPanelHTML(){
  var T=tpls(),h='<section class="panel"><div class="panel-head"><div><h2>Automatic WhatsApp sending</h2><p class="sub">Reminders go out from the SAA WhatsApp Business number. The server sends them straight through Meta, using the 7 templates Meta approved. Anyone with HR or Admin access can send; view-only staff can still open messages in WhatsApp.</p></div></div>';
  var status,cls="";
  if(!mcpApi){status="Not available in this view.";cls="warn";}
  else if(!zap.listed){status="The server doesn't have the Meta WhatsApp token yet. Add META_TOKEN and META_PHONE_ID under Script properties in the Apps Script project (setup guide, step 5), then reload this page.";cls="warn";}
  else if(zap.auth==="needs_reauth"){status="The server needs its Meta token renewed (setup guide, step 5).";cls="bad";}
  else if(zap.error){status=zapErrMsg(zap.error);cls="bad";}
  else if(!zap.templates){status="The business number is connected. Check which templates Meta has approved.";}
  else{var n=Object.keys(zap.templates).length;status=n===7?"Ready. All 7 templates are approved.":n?(n+" of 7 templates approved. The rest can't be sent automatically yet."):"The business number is connected, but Meta hasn't approved any templates yet. They're usually approved within a day.";cls=n===7?"":"warn";}
  h+='<div class="note'+(cls?" "+cls:"")+'"><span>'+esc(status)+'</span></div>';
  if(mcpApi&&zap.listed){
    h+='<div class="table-wrap"><table><thead><tr><th>Template</th><th>Meta name</th><th>Status</th></tr></thead><tbody>'+STAGES.map(function(k){
      var ok=zap.templates&&zap.templates[k]!=null;
      return '<tr><td>'+esc(T[k].label)+'</td><td class="mono">'+META[k]+'</td><td>'+(zap.templates?(ok?'<span class="pill st-on">Approved</span>':'<span class="pill st-soon">Waiting for Meta</span>'):'<span class="muted">Not checked</span>')+'</td></tr>';
    }).join("")+'</tbody></table></div>';
    h+='<div class="form-foot" style="justify-content:flex-start"><button class="btn" data-act="zap-check"'+(zap.checking?' disabled':'')+'>'+(zap.checking?'Checking…':'Check approval status')+'</button></div>';
    if(canAdmin()){
      h+='<div id="testPanel" style="margin-top:18px;border-top:1px solid var(--line);padding-top:16px"><h3 style="font-size:19px;margin-bottom:4px">Send a test</h3><p class="sub" style="font-size:14px;color:var(--ink-2);margin-bottom:12px">Sends one real message to a number you choose, so you can see exactly what employees receive. Meta charges for it like any other message.</p>'+
        '<div class="set-grid" style="align-items:end"><div class="field"><label for="testPhone">Send to</label><input id="testPhone" type="tel" inputmode="tel" placeholder="050 123 4567" value="'+esc(ui.testPhone)+'"></div>'+
        '<div class="field"><label for="testTpl">Template</label><select id="testTpl">'+STAGES.map(function(k){return '<option value="'+k+'"'+(ui.testTpl===k?" selected":"")+'>'+esc(T[k].label)+'</option>';}).join("")+'</select></div></div>'+
        '<div class="form-foot" style="justify-content:flex-start"><button class="btn btn-primary" data-act="zap-test">'+ICON.send+'Send test message</button></div>'+
        (ui.testResult?'<div class="note'+(ui.testResult.ok?'':' bad')+'"><span>'+esc(ui.testResult.msg)+'</span></div>':'')+'</div>';
    }
  }
  var lr=data.sending&&data.sending.lastRun;
  if(canAdmin()){
    h+='<div class="set-grid" style="margin-top:18px;border-top:1px solid var(--line);padding-top:16px;align-items:start">'+
      '<div class="field"><label for="sendSup">Who gets each reminder</label><select id="sendSup"><option value="both"'+(toSupervisor()?" selected":"")+'>Employee and supervisor</option><option value="emp"'+(toSupervisor()?"":" selected")+'>Employee only</option></select><small>Supervisors receive the same approved message.</small></div>'+
      '<div class="field"><label for="dailySend">Daily automatic sending</label><select id="dailySend"><option value="off">Off</option><option value="on"'+(dailyOn()?" selected":"")+'>On: every morning, around 8:00 AM (UAE)</option></select><small>The server sends everything due each morning, then emails the owner a summary. Turn this on once your test message has arrived.</small></div></div>';
  } else {
    h+='<p class="hint" style="margin-top:14px">Daily automatic sending is <b>'+(dailyOn()?"on":"off")+'</b>. Only the owner or an admin can change it.</p>';
  }
  if(lr&&lr.at)h+='<p class="hint" style="margin-top:10px">Last automatic run: '+esc(fmtDT(lr.at))+' · '+plural(+lr.sent||0,"reminder")+' sent'+(+lr.failed?' · '+lr.failed+' failed':'')+(lr.note?' · '+esc(lr.note):'')+'</p>';
  var mm=monthAutoMessages(lastMonths(1)[0]);
  h+='<p class="hint" style="margin-top:10px">This month: '+plural(mm,"automatic message")+' · about AED '+(mm*META_AED).toFixed(2)+' in Meta charges. Details in Reports.</p>';
  h+='</section>';
  return h;
}
