  var upd={sent:{}};upd.sent[c.start]={};upd.sent[c.start][stage]={at:at,by:me.id||null,via:opts.via||"manual"};if(opts.via==="auto")upd.sent[c.start][stage].n=(opts.to||[]).length;
  var to=opts.to;
