    logActivity(id+"_"+c.start+"_"+stage,{type:"reminder",empNo:id,empName:e.name||"",position:e.position||"",stage:stage,label:T[stage].label,cycle:c.start,message:msg,to:to,failed:opts.failed||[],via:opts.via||"manual",at:at});
    if(!opts.quiet)toast((opts.via==="auto"?"Sent “":"Marked “")+T[stage].label+"” "+(opts.via==="auto"?"to ":"as sent to ")+(e.name||"#"+id)+".");
    if(ui.composeFor===id){ui.composeStage=null;}
