/* ================= import ================= */
var MONMAP={jan:1,feb:2,mar:3,apr:4,may:5,jun:6,jul:7,aug:8,sep:9,oct:10,nov:11,dec:12};
function mkDate(y,m,d){var s=y+"-"+pad2(m)+"-"+pad2(d);return isISO(s)?s:null;}
function parseDate(s){
  s=String(s||"").trim();if(!s)return null;var m;
  if((m=s.match(/^(\d{4})[-\/.](\d{1,2})[-\/.](\d{1,2})(?:[ T].*)?$/)))return mkDate(+m[1],+m[2],+m[3]);
  if((m=s.match(/^(\d{1,2})[-\/.](\d{1,2})[-\/.](\d{2,4})(?:[ T].*)?$/))){var y=+m[3];if(y<100)y+=2000;return mkDate(y,+m[2],+m[1]);}
  if((m=s.match(/^(\d{1,2})[\s\-\/.]*([A-Za-z]{3,9})[\s\-\/.,]*(\d{2,4})$/))){var mo=MONMAP[m[2].slice(0,3).toLowerCase()];var y2=+m[3];if(y2<100)y2+=2000;return mo?mkDate(y2,mo,+m[1]):null;}
  if((m=s.match(/^([A-Za-z]{3,9})\s+(\d{1,2}),?\s+(\d{4})$/))){var mo2=MONMAP[m[1].slice(0,3).toLowerCase()];return mo2?mkDate(+m[3],mo2,+m[2]):null;}
  if(/^\d{5}(\.\d+)?$/.test(s)){var n=Math.floor(+s);if(n>20000&&n<80000)return fromUTC(Date.UTC(1899,11,30)+n*86400000);}
  return null;
}
function splitRow(line,dl){
  var out=[],cur="",q=false;
  for(var i=0;i<line.length;i++){
    var ch=line.charAt(i);
    if(q){if(ch==='"'){if(line.charAt(i+1)==='"'){cur+='"';i++;}else q=false;}else cur+=ch;}
    else if(ch==='"'&&cur.trim()===""){q=true;cur="";}
    else if(ch===dl){out.push(cur);cur="";}
    else cur+=ch;
  }
  out.push(cur);
  return out.map(function(x){return x.trim();});
}
function mapHeader(row){
  var m={};
  row.forEach(function(h,i){
    var x=String(h).toLowerCase().replace(/[^a-z0-9#]+/g," ").trim();
    if(!x)return;
    if(m.sup==null&&/(supervisor|manager|foreman|toolpusher)/.test(x)&&/(phone|mobile|whatsapp|number|contact|tel|no)/.test(x)){m.sup=i;return;}
    if(m.id==null&&(/^(emp|employee|staff|badge|personnel)?\s*(no|number|num|id|#|code)$/.test(x)||x==="id")){m.id=i;return;}
    if(m.pos==null&&/(position|role|title|trade|job|designation)/.test(x)){m.pos=i;return;}
    if(m.site==null&&/^(site|rig|location|project|field|site name|rig name|work site|worksite)$/.test(x)){m.site=i;return;}
    if(m.start==null&&/start|joined|join date/.test(x)&&!/(off|end)/.test(x)){m.start=i;return;}
    if(m.phone==null&&/(phone|mobile|whatsapp|contact|cell|tel)/.test(x)&&!/(supervisor|manager|hr)/.test(x)){m.phone=i;return;}
    if(m.name==null&&/name/.test(x)&&!/(supervisor|manager|position)/.test(x)){m.name=i;return;}
  });
  return m;
}
function parseImport(text){
  text=String(text||"").replace(/^﻿/,"").replace(/\r\n?/g,"\n");
  var lines=text.split("\n").filter(function(l){return l.trim()!=="";});
  if(!lines.length)return null;
  var first=lines[0],dl=first.indexOf("\t")>=0?"\t":((first.match(/;/g)||[]).length>(first.match(/,/g)||[]).length?";":",");
  var table=lines.map(function(l){return splitRow(l,dl);});
  var hm=mapHeader(table[0]);
  var hasHeader=hm.name!=null||(hm.id!=null&&hm.pos!=null);
  var map=hasHeader?hm:{id:0,name:1,pos:2,phone:3,sup:4,start:5};
  var body=hasHeader?table.slice(1):table;
  var seen={},posLower={};
  ruleKeys().forEach(function(p){posLower[p.toLowerCase()]=p;});
  var siteLower={};siteKeys().forEach(function(k){siteLower[k.toLowerCase()]=k;});
  var rows=body.map(function(cells,ix){
    var g=function(k){return map[k]!=null&&cells[map[k]]!=null?String(cells[map[k]]).trim():"";};
    var r={line:ix+(hasHeader?2:1),id:g("id").replace(/\s+/g,""),name:g("name").replace(/\s+/g," "),posRaw:g("pos"),startRaw:g("start"),phoneRaw:g("phone"),supRaw:g("sup"),errors:[]};
    r.position=posLower[r.posRaw.toLowerCase()]||null;
    r.hasSite=map.site!=null;r.siteRaw=g("site");r.site=r.siteRaw?(siteLower[r.siteRaw.toLowerCase()]||null):"";
    r.start=parseDate(r.startRaw);
    r.phone=r.phoneRaw?waNum(r.phoneRaw):"";
    r.sup=r.supRaw?waNum(r.supRaw):"";
    if(!r.id)r.errors.push("missing employee number");
    else if(!ID_RE.test(r.id))r.errors.push("employee number has characters that aren't allowed");
    else if(seen[r.id])r.errors.push("same employee number as line "+seen[r.id]);
    if(r.id&&!seen[r.id])seen[r.id]=r.line;
    if(!r.name)r.errors.push("missing name");
    if(!r.position)r.errors.push(r.posRaw?"unknown position “"+r.posRaw+"” (add it in Settings)":"missing position");
    if(!r.start)r.errors.push(r.startRaw?"can't read date “"+r.startRaw+"”":"missing duty start date");
    if(r.site===null)r.errors.push("unknown site “"+r.siteRaw+"” (add it in Settings)");
    if(r.phone===null)r.errors.push("employee phone looks incomplete");
    if(r.sup===null)r.errors.push("supervisor phone looks incomplete");
    r.ok=!r.errors.length;
    r.update=r.ok&&!!findEmp(r.id);
    return r;
  });
  return {rows:rows,hasHeader:hasHeader,delim:dl};
}
function renderImportPreview(){
  var el=$("impPreview"),P=ui.importRows;
  if(ui.importing){
    var I=ui.importing,pct=I.total?Math.round((I.done+I.failed)/I.total*100):0;
    el.innerHTML='<div class="imp-sum"><span>'+(I.finished?"Import finished":"Importing…")+' <b>'+(I.done)+' / '+I.total+'</b>'+(I.failed?' · <span class="tag-bad">'+I.failed+' failed</span>':'')+'</span></div><div class="progress"><i style="width:'+pct+'%"></i></div>'+
      (I.error?'<div class="form-error">'+esc(I.error)+'</div>':'')+
      (I.finished?'<div class="form-foot" style="justify-content:flex-start"><button class="btn" data-act="imp-reset">Import more</button><button class="btn btn-primary" data-act="imp-close">Done</button></div>':'');
    return;
  }
  if(!P){el.innerHTML="";return;}
  var ok=P.rows.filter(function(r){return r.ok;}),bad=P.rows.filter(function(r){return !r.ok;}),upd=ok.filter(function(r){return r.update;}).length;
  var h='<div class="imp-sum"><span><b>'+ok.length+'</b> ready ('+(ok.length-upd)+' new, '+upd+' updates)</span>'+(bad.length?'<span class="tag-bad">'+bad.length+' need fixing</span>':'')+'<span class="muted">'+(P.hasHeader?"Header row found":"No header row: read as Employee No., Name, Position, Employee Phone, Supervisor Phone, Duty Start Date")+'</span></div>';
  var show=bad.concat(ok).slice(0,120);
  h+='<div class="table-wrap"><table><thead><tr><th>Line</th><th></th><th>No.</th><th>Name</th><th>Position</th><th>Duty start</th><th>Employee WhatsApp</th><th>Supervisor</th><th>Problem</th></tr></thead><tbody>'+
    show.map(function(r){
      return '<tr><td class="mono">'+r.line+'</td><td>'+(r.ok?(r.update?'<span class="tag-upd">Update</span>':'<span class="tag-new">New</span>'):'<span class="tag-bad">Fix</span>')+'</td><td class="mono">'+esc(r.id)+'</td><td>'+esc(r.name)+'</td><td>'+esc(r.position||r.posRaw)+'</td><td class="mono">'+(r.start?esc(dLong(r.start)):esc(r.startRaw))+'</td><td class="mono">'+(r.phone?esc(fmtPhone(r.phone)):esc(r.phoneRaw))+'</td><td class="mono">'+(r.sup?esc(fmtPhone(r.sup)):esc(r.supRaw))+'</td><td class="err">'+esc(r.errors.join("; "))+'</td></tr>';
    }).join("")+'</tbody></table></div>';
  if(P.rows.length>show.length)h+='<p class="hint" style="margin-top:8px">Showing '+show.length+' of '+P.rows.length+' rows. Problems are listed first.</p>';
  h+='<div class="form-foot"><button class="btn" data-act="imp-reset">Clear</button><button class="btn btn-primary" data-act="imp-run"'+(ok.length&&canSave()?"":" disabled")+'>'+ICON.up+'Import '+plural(ok.length,"employee")+'</button></div>';
  el.innerHTML=h;
}
function runImport(){
  var P=ui.importRows;if(!P||!canSave())return;
  var rows=P.rows.filter(function(r){return r.ok;});
  if(!rows.length)return;
  var I=ui.importing={total:rows.length,done:0,failed:0,updated:0,finished:false,error:null};
  renderImportPreview();
  var idx=0,stop=false;
  function writeRow(r){
    var now=new Date().toISOString();
    var payload={name:r.name,position:r.position,dutyStart:r.start,employeePhone:r.phone?"+"+r.phone:"",supervisorPhone:r.sup?"+"+r.sup:"",updatedAt:now,updatedBy:me.id||null};
    if(r.hasSite)payload.site=r.site||"";
    var exists=!!findEmp(r.id);
    if(!exists){payload.createdAt=now;payload.createdBy=me.id||null;}
    var ref=db.collection("employees").doc(r.id);
    return serial("employees/"+r.id,function(){return withRetry(function(){return exists?ref.update(payload):ref.set(payload);},5);}).then(function(){if(exists)I.updated++;});
  }
  function worker(){
    if(stop||idx>=rows.length)return Promise.resolve();
    var r=rows[idx++];
    return writeRow(r).then(function(){I.done++;},function(err){
      if(err&&err.code==="invalid_argument"&&I.done===0){stop=true;I.error=writeErrMsg(err);noteRefusal(err);}
      else if(err&&(err.code==="quota_exceeded"||err.code==="revoked")){stop=true;I.error=writeErrMsg(err);}
      I.failed++;
    }).then(function(){renderImportPreview();return worker();});
  }
  Promise.all([worker(),worker(),worker()]).then(function(){
    I.finished=true;
    if(I.done)logActivity(null,{type:"import",count:I.done,updated:I.updated});
    renderImportPreview();
    toast(I.done?"Imported "+plural(I.done,"employee")+".":"Nothing was imported.",!I.done);
  });
}

/* ================= export ================= */
function csvCell(v){v=v==null?"":String(v);return /[",\n\r]/.test(v)?'"'+v.replace(/"/g,'""')+'"':v;}
function exportCSV(btn){
  var head=["Employee No.","Name","Position","Site","Rotation","Duty Start Date","Duty End Date","Off Start Date","Off End Date","Expected Return","Status","Days To Return","Employee Phone","Supervisor Phone","Swing Partner No.","On Leave Until","Late Returns","Late Days"];
  var rows=cache.rows.slice().sort(function(a,b){return cmpText(a.e.id,b.e.id);}).map(function(r){
    var e=r.e,c=r.c;
    var st=c?{on:"On duty",off:"Off duty",soon:"Returning soon",today:"Return date today",overdue:"Overdue / not returned",scheduled:"Scheduled"}[c.status]:"Needs rotation rule";
    return [e.id,e.name,e.position,e.site||"",c?c.duty+"/"+c.off:"",e.dutyStart,c?c.dutyEnd:"",c?c.offStart:"",c?c.offEnd:"",c?c.back:"",st,c?c.remaining:"",e.employeePhone,e.supervisorPhone,e.partner||"",r.onLeave?r.onLeave.to:"",r.late?r.late.late:0,r.late?r.late.lateDays:0];
  });
  var csv="﻿"+[head].concat(rows).map(function(r){return r.map(csvCell).join(",");}).join("\r\n");
  var fallback=function(){
    try{navigator.clipboard.writeText(csv.replace(/^﻿/,"")).then(function(){toast("Copied the crew list as CSV. Paste it into a spreadsheet.");},function(){toast("Export isn't available in this view.",true);});}
    catch(e){toast("Export isn't available in this view.",true);}
  };
  if(!dl){fallback();return;}
  dl.save({filename:"crew-rotation-"+todayISO()+".csv",data:csv}).then(function(r){if(r&&r.status==="saved")toast("Exported "+plural(rows.length,"employee")+".");})
  .catch(function(err){var c=err&&err.code;if(c==="declined")return;if(c==="rate_limited"){toast("A save prompt is already open.");return;}fallback();});
}

